CREATE TABLE students (
  id   bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  name text NOT NULL
);

CREATE TABLE courses (
  id    bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  title text NOT NULL
);

-- many-to-many junction table
CREATE TABLE enrollments (
  student_id  bigint NOT NULL REFERENCES students(id) ON DELETE CASCADE,
  course_id   bigint NOT NULL REFERENCES courses(id),
  enrolled_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (student_id, course_id)
);

SET lock_timeout = '5s';
ALTER TABLE users ADD COLUMN plan text NOT NULL DEFAULT 'free'; -- instant on PG 11+

ALTER TABLE users ADD CONSTRAINT users_email_not_null CHECK (email IS NOT NULL) NOT VALID;
ALTER TABLE users VALIDATE CONSTRAINT users_email_not_null;

CREATE INDEX CONCURRENTLY idx_users_plan ON users (plan);

